{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required_symbols = set(case.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}

    retained = set()
    for node in nodes:
        if not node.get("removable", False) or node.get("symbol") in required_symbols:
            retained.add(node["id"])

    pending = list(retained)
    while pending:
        node_id = pending.pop()
        node = by_id.get(node_id)
        if node is None:
            continue
        parent_id = node.get("parent")
        if parent_id in by_id and parent_id not in retained:
            retained.add(parent_id)
            pending.append(parent_id)

    removed_node_ids = [
        node["id"]
        for node in nodes
        if node.get("removable", False) and node["id"] not in retained
    ]
    retained_node_ids = [
        node["id"]
        for node in nodes
        if node["id"] not in set(removed_node_ids)
    ]

    return {
        "removed_node_ids": removed_node_ids,
        "retained_node_ids": retained_node_ids,
    }"}
